import type { CompiledCircuit } from "./circuit-types"

function toHex(bytes: Uint8Array): string {
  let hex = ""
  for (const byte of bytes) hex += byte.toString(16).padStart(2, "0")
  return hex
}

export async function proveWithWasm(params: {
  circuit: CompiledCircuit
  witness: Uint8Array
}): Promise<`0x${string}`> {
  const { Barretenberg, UltraHonkBackend } = await import("@aztec/bb.js")

  const api = await Barretenberg.new()
  try {
    const backend = new UltraHonkBackend(params.circuit.bytecode, api)
    // keccakZK, always: the on-chain verifiers are generated by
    // `bb write_solidity_verifier` (ZK Honk, keccak oracle) and hard-check the
    // proof length. bb.js's default flavour emits a differently-sized proof
    // that every deployed verifier rejects at the length gate.
    const proofData = await backend.generateProof(params.witness, { keccakZK: true })
    return `0x${toHex(proofData.proof)}` as `0x${string}`
  } finally {
    await api.destroy()
  }
}
